(() => {
  const Z=window.Zucco, {state,escape:E,icon:I,avatar:A,badge:B,btn:BT}=Z;
  const sourceIcons={Instagram:'instagram',Telegram:'telegram',Website:'globe',Referral:'users'};
  function leadCard(lead){
    const enrolled=lead.stage===Z.STAGES.length-1;
    return `<article class="lead-card" draggable="${!enrolled}" data-lead="${lead.id}" aria-label="${E(lead.name)}, ${Z.STAGES[lead.stage]}" data-component="LeadCard">
      <h3 class="lead-name truncate" title="${E(lead.name)}">${E(lead.name)}</h3>
      <p class="lead-phone mono">${E(lead.phone)}</p>
      <span class="course-tag" title="${E(lead.course)}">${E(lead.course)}</span>
      <div class="lead-meta"><span class="lead-source">${I(sourceIcons[lead.source])}${E(lead.source)}</span><span class="time-badge">${I('clock')}${lead.age}</span></div>
      <div class="lead-footer">${A(lead.assignee,'slate','small')}${enrolled?`<span class="lead-enrolled">${I('checkCircle')}Enrolled</span>`:`<button class="btn" type="button" data-action="convert:${lead.id}">${I('convert')}Convert to Student</button><button class="icon-btn" type="button" aria-label="Move ${E(lead.name)} to next stage" title="Move to next stage" data-action="advance:${lead.id}">${I('chevron')}</button>`}</div>
    </article>`;
  }
  Z.filteredLeads=()=>state.leads.filter(l=>(l.name+' '+l.phone).toLowerCase().includes(state.leadSearch.toLowerCase())&&(state.leadCourse==='all'||l.course===state.leadCourse)&&(state.leadAssignee==='all'||l.assignee===state.leadAssignee)&&(state.leadSource==='all'||l.source===state.leadSource));
  Z.leadBoard=()=>Z.STAGES.map((stage,i)=>{
    const leads=Z.filteredLeads().filter(l=>l.stage===i);
    return `<section class="kanban-column" data-stage="${i}" aria-label="${stage}" data-component="KanbanColumn"><header class="column-header"><span class="stage-dot stage-${i}"></span><h2>${stage}</h2><span class="column-count mono">${leads.length}</span><button class="icon-btn" type="button" data-action="new-lead:${i}" aria-label="Add lead to ${stage}">${I('plus')}</button></header>${leads.map(leadCard).join('')}<button type="button" class="add-lead-inline" data-action="new-lead:${i}">${I('plus')}Add lead</button></section>`;
  }).join('');
  function listView(){
    return `<div class="panel table-scroll"><table class="compact-table"><thead><tr><th style="width:23%">Lead</th><th>Course</th><th>Stage</th><th>Source</th><th style="width:17%">Action</th></tr></thead><tbody>${Z.filteredLeads().map(l=>`<tr><td><div class="table-primary">${E(l.name)}</div><div class="table-secondary mono">${E(l.phone)}</div></td><td>${E(l.course)}</td><td>${B(Z.STAGES[l.stage],l.stage===5?'success':'accent')}</td><td>${E(l.source)}</td><td>${l.stage===5?B('Enrolled','success'):BT('Convert to Student','convert:'+l.id,'convert','small')}</td></tr>`).join('')}</tbody></table></div>`;
  }
  Z.renderLeadsBody=()=>state.leadView==='pipeline'?`<div class="board-scroll"><div class="kanban" id="kanban-board">${Z.leadBoard()}</div></div>`:listView();
  Z.renderers[Z.ROUTES.LEADS]=()=>Z.heading('Leads','Turn the first conversation into a lifelong learner.',BT('Import leads','import-leads','download')+BT('Add lead','new-lead:0','plus','primary'))+
    `<div class="view-tabs" aria-label="Lead views"><button type="button" class="view-tab ${state.leadView==='pipeline'?'active':''}" data-action="lead-view:pipeline" aria-pressed="${state.leadView==='pipeline'}">${I('leads')}Pipeline<span class="count">${state.leads.length}</span></button><button type="button" class="view-tab ${state.leadView==='list'?'active':''}" data-action="lead-view:list" aria-pressed="${state.leadView==='list'}">${I('users')}All leads<span class="count">${state.leads.length}</span></button><div class="grow"></div><span class="caption" style="padding-bottom:12px">Admissions · November 2026</span></div>
    <div class="toolbar"><label class="input-search">${I('search')}<input id="lead-search" type="search" placeholder="Search name or phone…" value="${E(state.leadSearch)}" aria-label="Search leads"></label>
      <select id="lead-course" class="select" aria-label="Filter course"><option value="all">All courses</option>${['IELTS Foundation','General English','Mathematics','Frontend Development'].map(c=>`<option ${state.leadCourse===c?'selected':''}>${c}</option>`).join('')}</select>
      <select id="lead-assignee" class="select" aria-label="Filter assignee"><option value="all">All assignees</option>${['Madina Karimova','Aziza Rahimova'].map(c=>`<option ${state.leadAssignee===c?'selected':''}>${c}</option>`).join('')}</select>
      <select id="lead-source" class="select" aria-label="Filter source"><option value="all">All sources</option>${['Instagram','Telegram','Website','Referral'].map(c=>`<option ${state.leadSource===c?'selected':''}>${c}</option>`).join('')}</select><div class="toolbar-spacer"></div>${BT('Newest first','sort-leads','sort')}${BT('Reset filters','reset-leads','filter','ghost small')}
    </div><div class="board-summary"><span><strong>${state.leads.length}</strong> total leads</span><span><strong>${state.leads.filter(l=>l.stage===2||l.stage===3).length}</strong> at trial stage</span><span><strong>${state.leads.filter(l=>l.stage===4).length}</strong> awaiting payment</span><div class="grow"></div><span>Pipeline value <strong class="mono">24,800,000 UZS</strong></span></div>
    <div id="leads-body">${Z.renderLeadsBody()}</div><div class="board-footer"><span>Drag a card to move stages. Use the arrow on a card to move it with the keyboard.</span><span>Showing ${Z.filteredLeads().length} leads · Sample data</span></div>`;
  Z.moveLead=(id,stage)=>{const lead=state.leads.find(l=>l.id===id);if(!lead)return;lead.stage=stage;Z.render();Z.toast(`${lead.name} moved to ${Z.STAGES[stage]}`);};
  Z.showConversion=id=>{const l=state.leads.find(l=>l.id===id);if(!l)return;Z.actionDialog(`<div class="dialog-body"><div class="dialog-title-row"><h2 id="action-title">Convert to student</h2>${BT('','close-action','close','ghost small')}</div><p>Create a student profile and enroll ${E(l.name.split(' ')[0])} in a group.</p><div class="conversion-details"><div class="row between"><span class="caption">Student</span><strong>${E(l.name)}</strong></div><div class="row between"><span class="caption">Phone</span><span class="mono">${E(l.phone)}</span></div><div class="row between"><span class="caption">Course</span>${B(l.course,'accent')}</div></div><label class="field-label" for="convert-group" style="margin-top:18px">Enroll in group</label><select id="convert-group" class="select field-control"><option>${E(l.course)} · November cohort</option><option>Create profile without a group</option></select></div><div class="dialog-footer">${BT('Cancel','close-action')}${BT('Convert to Student','confirm-convert:'+id,'convert','primary')}</div>`);};
  Z.showNewLead=(stage=0)=>Z.actionDialog(`<form id="new-lead-form" data-stage="${stage}"><div class="dialog-body"><div class="dialog-title-row"><h2 id="action-title">New lead</h2>${BT('','close-action','close','ghost small')}</div><p>Add a new conversation to your admissions pipeline.</p><div class="action-form"><label class="stack"><span class="field-label">Full name <span class="required">*</span></span><input required class="input" name="name" autocomplete="off" placeholder="e.g. Azizbek Karimov" maxlength="70"></label><label class="stack"><span class="field-label">Phone number <span class="required">*</span></span><input required class="input" name="phone" type="tel" pattern="\\+?[0-9 ]{9,20}" placeholder="+998 90 123 45 67"></label><label class="stack"><span class="field-label">Course</span><select class="select" name="course"><option>IELTS Foundation</option><option>General English</option><option>Mathematics</option><option>Frontend Development</option></select></label><label class="stack"><span class="field-label">Source</span><select class="select" name="source"><option>Instagram</option><option>Telegram</option><option>Website</option><option>Referral</option></select></label></div></div><div class="dialog-footer">${BT('Cancel','close-action')}<button class="btn primary" type="submit">${I('plus')}Add lead</button></div></form>`);
})();
